    return ([lhs.program.rawValue, lhs.tone.rawValue, lhs.headline, lhs.summary] + lhs.tickerItems)
      .lexicographicallyPrecedes([rhs.program.rawValue, rhs.tone.rawValue, rhs.headline, rhs.summary] + rhs.tickerItems)
  }
}
